gLY(){return"\u0905\u0928\u0941\u092c\u0902\u0927 \u0938\u092e\u093e\u092a\u094d\u0924 \u0939\u094b\u0928\u0947 \u0915\u093e \u0915\u093e\u0930\u0923, \u0915\u093e\u092e \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f \u0914\u0930 \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u0905\u0928\u0941\u092d\u0935 \u0915\u093e \u0935\u0930\u094d\u0923\u0928 \u0915\u0930\u0947\u0902\u0964"},
gLP(){return"\u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0928\u0947 \u0915\u093e\u092e \u0915\u094d\u092f\u094b\u0902 \u0930\u094b\u0915\u093e, \u0905\u0928\u0941\u092c\u0902\u0927 \u0915\u094d\u092f\u094b\u0902 \u0938\u092e\u093e\u092a\u094d\u0924 \u0939\u0941\u0906, \u0915\u093e\u092e \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f \u0914\u0930 \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u0905\u0928\u0941\u092d\u0935 \u0915\u093e \u0935\u0930\u094d\u0923\u0928 \u0915\u0930\u0947\u0902\u0964"},
gMo(){return"\u092c\u093e\u0926 \u092e\u0947\u0902"},
gLU(){return"\u0905\u092a\u0928\u093e \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0902"},
