gG3(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u0430\u044f \u0436\u0430\u043b\u043e\u0431\u0430"},
Gn(a){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439: "+a+" \u0438\u0437 32"},
GH(a,b,c,d){return"\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439 - "+a+": "+b+"; "+c+": "+d+"."},
Gq(a){return"\u0414\u0440\u0443\u0433\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u0441\u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435 "+a+"."},
gGP(){return"\u0417\u0430\u043a\u0430\u0437\u0447\u0438\u043a"},
gGQ(){return"\u0418\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c"},
gG4(){return"\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0443\u0436\u0435 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e \u0432\u0430\u043c\u0438. \u0414\u043e\u0436\u0434\u0438\u0442\u0435\u0441\u044c \u043e\u0442\u0432\u0435\u0442\u0430 \u0434\u0440\u0443\u0433\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b."},
Ga(a){return"\u041e\u0442\u0432\u0435\u0442 \u0441\u0442\u0430\u043d\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u043f\u043e\u0441\u043b\u0435 "+a+". \u0421\u0443\u0442\u043e\u0447\u043d\u0430\u044f \u043f\u0430\u0443\u0437\u0430 \u043d\u0443\u0436\u043d\u0430 \u0434\u043b\u044f \u0432\u0437\u0432\u0435\u0448\u0435\u043d\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430."},
gGb(){return"\u0421\u0443\u0442\u043e\u0447\u043d\u0430\u044f \u043f\u0430\u0443\u0437\u0430 \u043f\u0435\u0440\u0435\u0434 \u043e\u0442\u0432\u0435\u0442\u043e\u043c \u0435\u0449\u0451 \u043d\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0430\u0441\u044c."},
gG7(){return"\u041b\u0438\u043c\u0438\u0442 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439 \u0432 \u044d\u0442\u043e\u0439 \u0436\u0430\u043b\u043e\u0431\u0435 \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d. \u041d\u043e\u0432\u044b\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f."},
gG9(){return"\u041f\u0438\u0441\u0430\u0442\u044c \u0437\u0434\u0435\u0441\u044c \u043c\u043e\u0433\u0443\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a \u0438 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u0439 \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c. \u041f\u0440\u043e\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0442\u044c \u0434\u0438\u0430\u043b\u043e\u0433 \u043c\u043e\u0433\u0443\u0442 \u0432\u0441\u0435 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u0437\u0430\u043a\u0430\u0437."},
gG6(){return"\u0413\u043e\u0434\u0438\u0447\u043d\u044b\u0439 \u0441\u0440\u043e\u043a \u043f\u043e\u0434\u0430\u0447\u0438 \u0436\u0430\u043b\u043e\u0431\u044b \u043f\u043e \u044d\u0442\u043e\u043c\u0443 \u0437\u0430\u043a\u0430\u0437\u0443 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0441\u044f."},
gG8(){return"\u0416\u0430\u043b\u043e\u0431\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0437\u0430\u043a\u0430\u0437\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u044b\u043b \u0432 \u0441\u0442\u0430\u0442\u0443\u0441\u0435 \xab\u0412 \u0440\u0430\u0431\u043e\u0442\u0435\xbb."},
gG5(){return"\u0423 \u044d\u0442\u043e\u0433\u043e \u0437\u0430\u043a\u0430\u0437\u0430 \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u044b\u0439 \u0434\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b."},
gGc(){return"\u0412 \u0442\u0435\u043a\u0443\u0449\u0435\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0436\u0430\u043b\u043e\u0431\u044b \u043d\u0435\u043b\u044c\u0437\u044f."},
gGx(){return"\u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435: \u043f\u043e\u0441\u0442\u0443\u043f\u0438\u043b\u0430 \u0436\u0430\u043b\u043e\u0431\u0430"},
Gs(a){return"\u041f\u043e \u0437\u0430\u043a\u0430\u0437\u0443 \xab"+a+"\xbb \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0436\u0430\u043b\u043e\u0431\u044b. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0434\u0438\u0430\u043b\u043e\u0433, \u0447\u0442\u043e\u0431\u044b \u043e\u0437\u043d\u0430\u043a\u043e\u043c\u0438\u0442\u044c\u0441\u044f \u0441 \u043d\u0438\u043c."},
gGw(){return"\u041d\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0432 \u0434\u0438\u0430\u043b\u043e\u0433\u0435 \u0436\u0430\u043b\u043e\u0431\u044b"},
Gv(a){return"\u0412 \u0434\u0438\u0430\u043b\u043e\u0433\u0435 \u0436\u0430\u043b\u043e\u0431\u044b \u043f\u043e \u0437\u0430\u043a\u0430\u0437\u0443 \xab"+a+"\xbb \u043f\u043e\u044f\u0432\u0438\u043b\u043e\u0441\u044c \u043d\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0434\u0438\u0430\u043b\u043e\u0433, \u0447\u0442\u043e\u0431\u044b \u043e\u0437\u043d\u0430\u043a\u043e\u043c\u0438\u0442\u044c\u0441\u044f \u0441 \u043d\u0438\u043c."},
gGt(){return"\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0434\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b"},
gGu(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043c\u0435\u0442\u0438\u0442\u044c \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0435 \u043e \u0436\u0430\u043b\u043e\u0431\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u043c - \u043e\u043d\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0441\u043d\u043e\u0432\u0430."},
Ku(a){return"\u041d\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0436\u0430\u043b\u043e\u0431\u044b \u043f\u043e \u0437\u0430\u043a\u0430\u0437\u0443 "+a},
gGd(){return"\u0416\u0430\u043b\u043e\u0431\u0430"},
